def test_generated_table_covers_requested_sources_and_replacements():
    assert len(CASES) >= 300
    assert {case[1] for case in CASES} == {"lf", "crlf", "cr", "mixed"}
    assert {case[2] for case in CASES} == {"lf", "crlf", "cr", "mixed"}
    assert any("\f" in case[3] for case in CASES)
    assert any("\x1c" in case[3] for case in CASES)
    assert any("\u2028" in case[3] for case in CASES)
    assert any("\u0085" in case[3] for case in CASES)
    assert any("\t" in case[3] for case in CASES)
    assert any("é" in case[3] for case in CASES)
    assert any("@" in case[3] for case in CASES)
    assert any("class Outer:" in case[3] for case in CASES)
    assert any("\f" in case[3] and "class Outer:" in case[3]
               and case[5] == "candidate" and case[6] for case in CASES)
    assert any(case[5] == "candidate" and case[6] for case in CASES)
    assert any(case[5] == "raises:IndexError" for case in CASES)
    assert any(case[3].startswith(("class Target:", "@decorate")) for case in CASES)
    assert any(case[3].rstrip("\n\r").endswith(f"old_generation = {case[0]}") for case in CASES)
    assert any(not case[3].endswith(("\n", "\r")) for case in CASES)
    assert any(not case[4].endswith(("\n", "\r")) for case in CASES)


def _assert_candidate(plan, index, prefix, suffix):
    assert plan.handled is True, f"case {index} was left unhandled"
    assert plan.rejection is None, f"case {index} was newly refused: {plan.rejection}"
    assert plan.candidate is not None
    ast.parse(plan.candidate, filename=f"candidate-{index}.py")
    assert plan.candidate.startswith(prefix), f"case {index} changed bytes before Target"
    assert plan.candidate.endswith(suffix), f"case {index} changed bytes after Target"
    assert f"generation = {index}" in plan.candidate


def test_generated_differential_cases_preserve_accepted_behavior_and_boundaries():
    for (
        index, source_mode, payload_mode, source, replacement, base_kind,
        base_safe, base_candidate, base_rejection, prefix, suffix,
    ) in CASES:
        try:
            plan = prepare_class_edit(
                source, "Target", replacement, path=pathlib.Path("generated.py"),
            )
        except Exception as exc:
            pytest.fail(f"case {index} ({source_mode}/{payload_mode}, base={base_kind}) raised {type(exc).__name__}: {exc}")

        if base_kind == "candidate":
            _assert_candidate(plan, index, prefix, suffix)
            if base_safe:
                assert plan.candidate == base_candidate, f"case {index} diverged from the valid base result"
        elif base_kind == "rejection":
            if plan.candidate is None:
                assert json.loads(plan.rejection)["code"] == json.loads(base_rejection)["code"], (
                    f"case {index} changed the base rejection category"
                )
            else:
                _assert_candidate(plan, index, prefix, suffix)
        elif base_kind.startswith("raises:"):
            if plan.candidate is not None:
                _assert_candidate(plan, index, prefix, suffix)
            else:
                assert plan.handled is True
                assert plan.rejection is not None
                assert json.loads(plan.rejection)["code"] == "INVALID_CLASS_RESULT"
        else:
            assert plan.handled is False


def test_unexpected_indexerror_becomes_typed_rejection(monkeypatch):
    def fail_offset(*_args, **_kwargs):
        raise IndexError("synthetic bad AST offset")

    monkeypatch.setattr(edit, "_offset", fail_offset)
    plan = prepare_class_edit(
        "class Target:\n    old = 1\n",
        "Target",
        "class Target:\n    new = 1\n",
        path=pathlib.Path("typed_refusal.py"),
    )

    assert plan.handled is True
    assert plan.candidate is None
    assert plan.rejection is not None
    assert json.loads(plan.rejection)["code"] == "INVALID_CLASS_RESULT"
    assert "synthetic bad AST offset" not in plan.rejection
